CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE `ALARM_SESSION` (`ID` TEXT NOT NULL, `INTERVAL` INTEGER NOT NULL, `CYCLE_TYPE` TEXT, `START_TIME` TEXT, `TIME_IN_MILLIS` INTEGER NOT NULL, `SAVE` INTEGER NOT NULL, `TIME_UNIT` INTEGER NOT NULL, `WEEK_TYPE` INTEGER NOT NULL, `REQUEST` TEXT, `PARAMS` TEXT, `CREATE_TIME` TEXT, PRIMARY KEY(`ID`));
CREATE TABLE `SYS_DICT` (`_id` INTEGER PRIMARY KEY AUTOINCREMENT, `NAME` TEXT, `DESCRIPTION` TEXT, `CREATE_BY` TEXT, `UPDATE_BY` TEXT, `CREATE_TIME` INTEGER, `UPDATE_TIME` INTEGER);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE `SYS_DICT_DETAIL` (`DETAIL_ID` TEXT NOT NULL, `DICT_ID` INTEGER, `LABEL` TEXT, `VALUE` TEXT, `DICT_SORT` INTEGER, `CREATE_BY` TEXT, `UPDATE_BY` TEXT, `CREATE_TIME` INTEGER, `UPDATE_TIME` INTEGER, PRIMARY KEY(`DETAIL_ID`));
CREATE TABLE `CLEAN_STRATEGY` (`ID` TEXT NOT NULL, `CLEAN_NAME` TEXT, `MAP_ID` TEXT, `TARGET_MAP_ID` TEXT, `DEFINITE_TYPE` TEXT, `CYCLE_TYPE` TEXT, `CYCLE_DETAIL` TEXT, `START_TIME` TEXT, `FINISH_TIME` TEXT, `STATE` TEXT, `CLEAN_AREA_ALL_ENABLE` INTEGER, `VIEW_STATUS` INTEGER, `STRATEGY_ENABLE` INTEGER, `DISABLE_STATUS` INTEGER, `VERSION` INTEGER, `STRATEGY_MAP_AREA_ID` TEXT, `STRATEGY_TYPE` INTEGER, `CLEAN_FINISH_TYPE` INTEGER, `CLEAN_MAP_AREA` TEXT, `ROBOT_CLEAN_CONFIG_INFO` TEXT, `CLEAN_JOB_ALARM_IDS` TEXT, `CREATE_TIME` INTEGER, `UPDATE_TIME` INTEGER, `SYNC_STATE` INTEGER, `CLEAN_MAP_CONFIGS` TEXT, `CLEAN_AREA` REAL, `CLEAN_DURATION` INTEGER, `BACK_POINT` TEXT, `SOURCE` TEXT, PRIMARY KEY(`ID`));
CREATE TABLE `ELEVATOR` (`_id` INTEGER, `NAME` TEXT, `CREATE_TIME` INTEGER, `UPDATE_TIME` INTEGER, PRIMARY KEY(`_id`));
CREATE TABLE `ELEVATOR_FLOOR` (`ID` TEXT NOT NULL, `FLOOR_NUMBER` INTEGER, `NAME` TEXT, `ELEVATOR_ID` INTEGER, `CONFIG_STATUS` INTEGER, `MAP_ID` TEXT, `CREATE_TIME` INTEGER, `UPDATE_TIME` INTEGER, PRIMARY KEY(`ID`));
CREATE TABLE `MAP_AREA` (`ID` TEXT NOT NULL, `ROS_ID` INTEGER, `MD5` TEXT, `PARENT_ID` TEXT, `MAP_ID` TEXT, `MAP_MD5` TEXT, `DRAW_TYPE` INTEGER, `AREA_TYPE` INTEGER, `AREA_MATERIAL_TYPE` INTEGER, `AREA_NAME` TEXT, `AREA_POINTS` TEXT, `AREA_POINTS_WEB` TEXT, `SORT_NUM` INTEGER, `INDEX_NUM` INTEGER, `AREA_TEACH_WAY` TEXT, `AREA_TEACH_WAY_WEB` TEXT, `ELEVATOR_ID` INTEGER, `LAST_POSITION` TEXT, `REGIONS` REAL, `AREA_ROUTE` TEXT, `CREATE_TIME` INTEGER, `UPDATE_TIME` INTEGER, `DELETED` INTEGER DEFAULT 0, `TEACH_PATH_LENGTH` REAL DEFAULT 0, PRIMARY KEY(`ID`));
CREATE TABLE `MAP_POINTS` (`ID` TEXT NOT NULL, `ROS_ID` INTEGER, `CONSOLE_POINT_ID` INTEGER, `NAME` TEXT, `MAP_ID` TEXT, `POINT_TYPE` INTEGER, `POINT_META_TYPE` INTEGER, `COORDS_INFO` TEXT, `ELEVATOR_ID` INTEGER, `CREATE_TIME` INTEGER, `UPDATE_TIME` INTEGER, IS_DEFAULT_CHARGE INTEGER DEFAULT 0, PRIMARY KEY(`ID`));
CREATE TABLE `MAP_VIRTUAL_WALL` (`ID` TEXT NOT NULL, `MAP_ID` TEXT, `VIRTUAL_NAME` TEXT, `TYPE` INTEGER, `CREATE_TIME` INTEGER, `UPDATE_TIME` INTEGER, `COORDS_INFO` TEXT, `COORDS_INFO_WEB` TEXT, `STROKE_COLOR` TEXT, `STROKE_WIDTH` INTEGER, PRIMARY KEY(`ID`));
CREATE TABLE `RECHARGE_LOG` (`ID` TEXT NOT NULL, `MAP_ID` TEXT, `OPERATE_SOURCE` TEXT, `STATUS` INTEGER, `DESC` TEXT, `CREATE_TIME` INTEGER, `LAST_UPDATE_TIME` INTEGER, PRIMARY KEY(`ID`));
CREATE TABLE `ROBOT_MAP` (`MAP_ID` TEXT NOT NULL, `FLOOR` INTEGER, `MD5` TEXT, `ROBOT_CODE` TEXT, `MAP_NAME` TEXT, `MAP_INDEX` INTEGER, `PIC` TEXT, `PIC_BASE` TEXT, `COMPOSE_VIEW_PIC` TEXT, `CREATE_STATE` INTEGER, `VERSION` INTEGER, `THUMBNAIL` TEXT, `THUMBNAIL_URL` TEXT, `PIC_VERTEX_COORDINATES` TEXT, `MAP_ATTRIBUTE_PARAM` TEXT, `MAP_EDGE_URL` TEXT, `MAP_EDGE_BASE` TEXT, `LOAD_STATE` INTEGER, `CREATE_USER_ID` TEXT, `UPDATE_TIME` INTEGER, `CREATE_TIME` INTEGER, `DELETED` INTEGER, `SYNC_STATE` INTEGER, `DEFAULT_STATE` INTEGER, PRIMARY KEY(`MAP_ID`));
CREATE TABLE `MAP_DATA_HISTORY` (`MAP_VERSION_ID` TEXT NOT NULL, `MAP_DATA` TEXT, `CREATE_TIME` INTEGER, PRIMARY KEY(`MAP_VERSION_ID`));
CREATE TABLE `TASK_ATTACH_DETAIL` (`ID` TEXT NOT NULL, `TASK_SNAPSHOT` TEXT, `TASK_CLEAN_WAY` TEXT, `SYNC_STATE` INTEGER, PRIMARY KEY(`ID`));
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
